        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) IN ('Revoked', 'Blacklisted') THEN 'Black'
        WHEN COALESCE((
        SELECT es.warningLevel
        FROM official_registry r_chk
        LEFT JOIN enforcement_state es
          ON es.subjectType = 'business'
         AND es.subjectID = CAST(r_chk.businessID AS CHAR)
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ), (
        SELECT es.warningLevel
        FROM enforcement_state es
        WHERE es.subjectType = 'geospatial_log'
          AND es.subjectID = CAST(g.logID AS CHAR)
        LIMIT 1
    ), 0) >= 1 THEN 'Orange'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Active' THEN 'Green'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Expired' THEN 'Red'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Closed' THEN 'Purple'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Pending' THEN 'Yellow'
        ELSE g.flagColor
    END IN ('Red', 'Yellow') AND NOT EXISTS (
        SELECT 1 FROM inspection_reports pending
        WHERE pending.targetID = g.logID
          AND pending.verificationStatus IN ('Assigned', 'Reassigned', 'In Progress')
    )
        AND g.latitude BETWEEN -90 AND 90 AND g.longitude BETWEEN -180 AND 180 THEN g.longitude END)    AS avg_lng,
            COUNT(DISTINCT CASE WHEN CASE
        WHEN COALESCE(COALESCE((
        SELECT es.blackLocked
        FROM official_registry r_chk
        LEFT JOIN enforcement_state es
          ON es.subjectType = 'business'
         AND es.subjectID = CAST(r_chk.businessID AS CHAR)
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ), (
        SELECT es.blackLocked
        FROM enforcement_state es
        WHERE es.subjectType = 'geospatial_log'
          AND es.subjectID = CAST(g.logID AS CHAR)
        LIMIT 1
    ), 0), 0) <> 0 THEN 'Black'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) IN ('Revoked', 'Blacklisted') THEN 'Black'
        WHEN COALESCE((
        SELECT es.warningLevel
        FROM official_registry r_chk
        LEFT JOIN enforcement_state es
          ON es.subjectType = 'business'
         AND es.subjectID = CAST(r_chk.businessID AS CHAR)
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ), (
        SELECT es.warningLevel
        FROM enforcement_state es
        WHERE es.subjectType = 'geospatial_log'
          AND es.subjectID = CAST(g.logID AS CHAR)
        LIMIT 1
    ), 0) >= 1 THEN 'Orange'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Active' THEN 'Green'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Expired' THEN 'Red'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Closed' THEN 'Purple'
        WHEN (
        SELECT r_chk.applicationStatus
        FROM official_registry r_chk
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) = 'Pending' THEN 'Yellow'
        ELSE g.flagColor
    END = 'Red'
                AND (
        SELECT r_chk.businessID
        FROM official_registry r_chk
        
        WHERE (
            (r_chk.businessID IS NOT NULL AND g.businessID IS NOT NULL
                AND r_chk.businessID = g.businessID)
            OR (g.placeID IS NOT NULL AND r_chk.placeID = g.placeID
                AND (g.businessID IS NULL OR r_chk.businessID = g.businessID))
            OR (g.businessID IS NULL
                AND r_chk.barangayID = g.barangayID
                AND r_chk.businessName = g.detectedName)
        )
        ORDER BY (r_chk.businessID = g.businessID) DESC,
                 (r_chk.placeID = g.placeID) DESC
        LIMIT 1
    ) IS NULL THEN g.logID END) AS unregistered_candidate_count,
            COUNT(DISTINCT o.businessID)                             AS total_registered
        FROM barangays b
        LEFT JOIN geospatial_logs   g ON g.barangayID = b.barangayID
            AND (g.placeID IS NOT NULL OR g.reportedByUserID IS NOT NULL OR g.flagColor = 'Orange' OR EXISTS (SELECT 1 FROM inspection_reports ir WHERE ir.targetID = g.logID))
        LEFT JOIN official_registry o ON o.barangayID = b.barangayID AND 1=0
        WHERE 1=1 
        GROUP BY b.barangayID, b.barangayName
    ;

-- 2. Registry coverage per barangay

        SELECT b.barangayID,
               COUNT(DISTINCT o.businessID) AS total_registered,
               COUNT(DISTINCT CASE WHEN CASE
        WHEN COALESCE((
        SELECT es.blackLocked
        FROM enforcement_state es
        WHERE es.subjectType = 'business'
          AND es.subjectID = CAST(o.businessID AS CHAR)
        LIMIT 1
    ), 0) <> 0 THEN 'Black'
        WHEN o.applicationStatus IN ('Revoked', 'Blacklisted') THEN 'Black'
        WHEN COALESCE((
        SELECT es.warningLevel
        FROM enforcement_state es
        WHERE es.subjectType = 'business'
          AND es.subjectID = CAST(o.businessID AS CHAR)
        LIMIT 1
    ), 0) >= 1 THEN 'Orange'
        WHEN o.applicationStatus = 'Active' THEN 'Green'
        WHEN o.applicationStatus = 'Expired' THEN 'Red'
        WHEN o.applicationStatus = 'Closed' THEN 'Purple'
        WHEN o.applicationStatus = 'Pending' THEN 'Yellow'
        ELSE 'Yellow'
    END IN ('Red', 'Yellow', 'Black')
                     THEN o.businessID END) AS registry_flagged_count
        FROM barangays b
        LEFT JOIN official_registry o ON o.barangayID = b.barangayID
        GROUP BY b.barangayID
    ;

